func tlMap[A, B any](src []A, f func(A) B) []B {
	out := make([]B, len(src))
	for i, e := range src {
		out[i] = f(e)
	}
	return out
}

func tlJsonlines[T any](v []T, f func(T) string) string {
	parts := make([]string, len(v))
	for i, e := range v {
